(()=>{const online=()=>navigator.onLine;function banner(){let b=document.getElementById('nexaOfflineBanner');if(!b){b=document.createElement('div');b.id='nexaOfflineBanner';b.style.cssText='position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:99999;padding:10px 16px;border-radius:999px;background:#111827;color:#fff;font:600 13px system-ui;box-shadow:0 8px 30px #0008;display:none';b.textContent='Modalità offline · alcune funzioni richiedono Internet';document.body.appendChild(b)}b.style.display=online()?'none':'block'}window.addEventListener('online',banner);window.addEventListener('offline',banner);document.addEventListener('DOMContentLoaded',banner);})();